-- The organisation's saved Styles (D129 "My styles"; spec #168, ticket #177).
-- Generated by drizzle-kit (the table, its indexes and the `events` changes), then row-level
-- security and the updated_at trigger appended by hand (packages/db/src/table-access.ts says how).
--   1. `design_styles`: one row per Style the organisation saved, with a name unique among the ones
--      that are not removed (the partial index), the premade Style its values came from, the
--      Style's values (core's `StyleValues`: every choice option but the body font, so a Style
--      never carries a venue's brand) and its provenance, NOT NULL (rule 2). A delete sets
--      `removed_at`, which the owner's Undo clears; only the purge deletes rows (D83);
--   2. `events` may record a saved Style: the ops `setStyle` and `setStyleStatus`, each with no
--      node (as `setDesign` has none), the master scope (a Style is the organisation's, not a
--      venue's), the manual layer and the field key `style` or `style_status`;
--   3. row-level security, so a Style is its organisation's alone, and `updated_at`.
-- `pnpm db:roles` grants the app role SELECT, INSERT and UPDATE and nothing more; the purge role
-- holds nothing here (organisations are not purged). Runs on staging only with Martin's OK.

CREATE TABLE "restro"."design_styles" (
	"id" text PRIMARY KEY NOT NULL,
	"tenant_id" text NOT NULL,
	"name" text NOT NULL,
	"style" text NOT NULL,
	"style_values" jsonb NOT NULL,
	"removed_at" timestamp with time zone,
	"layer" text NOT NULL,
	"source" text NOT NULL,
	"actor" text NOT NULL,
	"job_id" text NOT NULL,
	"change_set_id" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "design_styles_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "design_styles_id_format" CHECK ("restro"."design_styles"."id" ~ '^ds_[0-9A-Za-z]+$'),
	CONSTRAINT "design_styles_name_length" CHECK (char_length("restro"."design_styles"."name") between 1 and 60 and "restro"."design_styles"."name" = btrim("restro"."design_styles"."name")),
	CONSTRAINT "design_styles_style_format" CHECK ("restro"."design_styles"."style" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
	CONSTRAINT "design_styles_values_object" CHECK (jsonb_typeof("restro"."design_styles"."style_values") = 'object'),
	CONSTRAINT "design_styles_layer" CHECK ("restro"."design_styles"."layer" = 'manual'),
	CONSTRAINT "design_styles_source" CHECK ("restro"."design_styles"."source" = 'manual'),
	CONSTRAINT "design_styles_actor" CHECK ("restro"."design_styles"."actor" ~ '^(user|integration):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'),
	CONSTRAINT "design_styles_job_id" CHECK (length("restro"."design_styles"."job_id") between 1 and 128),
	CONSTRAINT "design_styles_change_set_id" CHECK ("restro"."design_styles"."change_set_id" ~ '^cs_[0-9A-Za-z]+$')
);
--> statement-breakpoint
